var HSHLS_SETTINGS_PAGE="";
// ==================== hs local JS spider loader (patched) ====================

// ============================================================================
// hs-js-source-loader —— 把 cat(CatPaw) 引擎的「本地猫源 JS 脚本」能力移植到 hs 引擎
// ----------------------------------------------------------------------------
// 功能：
//  1) 扫描本地 js 目录，加载 *.js 猫源（ESM 单文件，export default 工厂函数）
//  2) 注入 __CAT_JS_UTIL 白名单（axios / cheerio / crypto-js / crypto / zlib /
//     util/req.js / util/htmlParser.js / util/pan.js / util/misc.js ...）
//  3) 动态注册 spider 路由（/spider/{key}/{type}/*），支持热重载（无需重启进程）
//  4) 提供 /js 管理 API（list / upload / file / order / config / reload）
//  5) 提供 /website/js 配置页面（配合 /website 首页菜单）
// ============================================================================
var HSJS_VERSION = "2.16.0";
var HSJS_ROUTES = new Map();
var HSJS_SOURCES = [];
var HSJS_FILES = [];
var HSJS_STATE = { loaded: false, dir: "", loading: null, lastReload: 0 };
var HSJS_DISPATCH_DONE = false;
var HSJS_REGISTRY = null;
// 每个源一份日志环形缓冲（脚本 console + 每次路由请求的摘要），供配置页「导出报告」查看
var HSJS_LOGS = new Map();
var HSJS_LOG_MAX = 600;
function hsjsFmt(v) {
  try {
    if (typeof v === "string") return v;
    if (v instanceof Error) return v.stack || v.message || String(v);
    if (v === undefined) return "undefined";
    return JSON.stringify(v);
  } catch (e) { return String(v); }
}
function hsjsLogBox(key) {
  var box = HSJS_LOGS.get(key);
  if (!box) { box = { lines: [] }; HSJS_LOGS.set(key, box); }
  return box;
}
function hsjsPushLog(key, lvl, msg) {
  if (!key) key = "-";
  var box = hsjsLogBox(key);
  box.lines.push({ t: Date.now(), lvl: lvl, msg: String(msg).slice(0, 3000) });
  if (box.lines.length > HSJS_LOG_MAX) box.lines.splice(0, box.lines.length - HSJS_LOG_MAX);
}
function hsjsConsole(key) {
  var mk = function (lvl) {
    return function () {
      var args = Array.prototype.slice.call(arguments);
      var text = args.map(hsjsFmt).join(" ");
      hsjsPushLog(key, lvl, text);
      try {
        if (lvl === "error") console.error("[js:" + key + "] " + text);
        else if (lvl === "warn") console.warn("[js:" + key + "] " + text);
        else console.log("[js:" + key + "] " + text);
      } catch (e) { }
    };
  };
  return { log: mk("log"), info: mk("info"), warn: mk("warn"), error: mk("error"), debug: mk("debug"), trace: mk("trace") };
}
// 每个本地源一份「站点上下文」：脚本可通过 globalThis.__HSJS_SITE__ 读写，
// 配置页面保存的「自定义域名」也会实时写进这里（无需重载即可生效）
var HSJS_SITES = new Map();

function hsjsDomainList(cfg) {
  var out = [];
  var add = function (v) {
    if (v === null || v === undefined) return;
    if (Array.isArray(v)) { v.forEach(add); return; }
    var parts = String(v).split(/[\s,;|]+/);
    for (var i = 0; i < parts.length; i++) {
      var d = parts[i].trim().replace(/^https?:\/\//i, "").replace(/\/+$/, "");
      if (!d || out.indexOf(d) >= 0) continue;
      if (!/^[a-z0-9][a-z0-9.\-]*\.[a-z]{2,}$/i.test(d) && !/^\d{1,3}(\.\d{1,3}){3}(:\d+)?$/.test(d)) continue;
      out.push(d);
    }
  };
  if (cfg) { add(cfg.domain); add(cfg.domains); add(cfg.host); add(cfg.hosts); }
  return out;
}

function hsjsSite(fileKey, config) {
  var domains = hsjsDomainList(config);
  return {
    key: fileKey || "",
    file: "",
    config: config || {},
    domains: domains,
    domain: "",
    gen: "",
    note: ""
  };
}

// 保存「自定义域名」后实时刷新（不用重启/重载即可让脚本读到新域名）
function hsjsApplyConfig(key, config) {
  var sites = [];
  HSJS_SITES.forEach(function (s, k) { if (k === key) sites.push(s); });
  sites.forEach(function (s) {
    s.config = config || {};
    s.domains = hsjsDomainList(config);
  });
  return sites.length;
}





// ---- 目录解析：NODE_PATH/hs，否则平台默认目录 ----
function hsjsDir() {
  var fs = require("fs");
  var path = require("path");
  var dir;
  if (process.env.NODE_PATH) {
    dir = path.resolve(process.env.NODE_PATH, "hs");
  } else {
    var home = require("os").homedir();
    switch (process.platform) {
      case "win32": dir = path.join(home, "Documents", "CatPaw", "js"); break;
      case "darwin": dir = path.join(home, "Library", "Application Support", "CatPaw", "js"); break;
      case "linux": dir = path.join(home, ".local", "share", "catpaw", "js"); break;
      default: dir = path.join(process.cwd(), "js");
    }
  }
  try { if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true }); } catch (e) { }
  return dir;
}

function hsjsKeyOf(fileName) {
  return String(fileName || "").replace(/\.js$/i, "").trim().replace(/[^\u4e00-\u9fa5a-zA-Z0-9_\-]/g, "_");
}

function hsjsSizeStr(size) {
  if (!size) return "0B";
  if (size < 1024) return size + "B";
  if (size < 1024 * 1024) return (size / 1024).toFixed(1) + "K";
  return (size / 1024 / 1024).toFixed(2) + "M";
}

// ---- 白名单模块注册表（等价 cat 的 __CAT_JS_UTIL） ----
function hsjsBuiltins() {
  var names = ["crypto", "zlib", "http", "https", "http2", "url", "querystring", "buffer", "stream",
    "util", "string_decoder", "assert", "events", "net", "tls", "dns", "os", "path", "punycode",
    "process", "readline", "timers"];
  var out = {};
  for (var i = 0; i < names.length; i++) {
    try { out[names[i]] = require(names[i]); } catch (e) { }
  }
  return out;
}

function hsjsDelay(ms) { return new Promise(function (r) { setTimeout(r, ms || 0); }); }

function hsjsJsonParse(v) {
  if (typeof v !== "string") return v;
  try { return JSON.parse(v); } catch (e) { return v; }
}

function hsjsStripHtml(html) {
  return String(html == null ? "" : html).replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
}

function hsjsFixUrl(url, base) {
  var raw = String(url == null ? "" : url).trim();
  if (!raw) return "";
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.indexOf("//") === 0) return "https:" + raw;
  try { return new URL(raw, base || undefined).toString(); } catch (e) { return raw; }
}

function hsjsUrljoin(base, url) {
  try { return new URL(String(url || ""), String(base || "")).toString(); } catch (e) { return String(url || ""); }
}

function hsjsJsonPath(data, expr) {
  // 极简 JSONPath：支持 $.a.b[0].c 与 a.b.c
  try {
    var pathExpr = String(expr || "").replace(/^\$\.?/, "");
    if (!pathExpr) return data;
    var parts = pathExpr.replace(/\[(\d+)\]/g, ".$1").split(".").filter(Boolean);
    var cur = data;
    for (var i = 0; i < parts.length; i++) {
      if (cur == null) return undefined;
      cur = cur[parts[i]];
    }
    return cur;
  } catch (e) { return undefined; }
}

function hsjsLRU(limit) {
  this.limit = limit || 100;
  this.cache = new Map();
}
hsjsLRU.prototype.get = function (k) {
  if (!this.cache.has(k)) return null;
  var v = this.cache.get(k);
  this.cache.delete(k); this.cache.set(k, v);
  return v;
};
hsjsLRU.prototype.set = function (k, v) {
  if (this.cache.has(k)) this.cache.delete(k);
  else if (this.cache.size >= this.limit) this.cache.delete(this.cache.keys().next().value);
  this.cache.set(k, v);
};
hsjsLRU.prototype.del = function (k) { this.cache.delete(k); };
hsjsLRU.prototype.clear = function () { this.cache.clear(); };
hsjsLRU.prototype.default = hsjsLRU;

function hsjsJsoup() { }
hsjsJsoup.prototype.pq = function (html) { return hsjsCheerioLoad(String(html == null ? "" : html)); };
