    getPans: function () { return globalThis.Pans || []; },
    getPanName: function (k) { return globalThis.getPanName ? globalThis.getPanName(k) : ""; },
    getPanEnabled: function (k) { return globalThis.getPanEnabled ? globalThis.getPanEnabled(k) : false; }
