    setTimeout: setTimeout, clearTimeout: clearTimeout,
    setInterval: setInterval, clearInterval: clearInterval,
    setImmediate: host.setImmediate, clearImmediate: host.clearImmediate,
    queueMicrotask: host.queueMicrotask,
    Buffer: Buffer, URL: URL, URLSearchParams: URLSearchParams,
    atob: host.atob, btoa: host.btoa,
    fetch: host.fetch, Headers: host.Headers, Request: host.Request,
