var HSD_PROBING = new Set();
var HSD_INFLIGHT = new Map();         // P4：匹配 in-flight 去重
var HSD_PUSH = { key: "", at: 0 };    // P4：auto-push 30s 去重
var HSD_MATCH_TTL = 30 * 60 * 1000, HSD_DETAIL_TTL = 6 * 60 * 60 * 1000, HSD_CACHE_MAX = 120;

function hsdPort(){
  try {
    var app = HSD_STATE && HSD_STATE.app;
    var ad = app && app.server && app.server.address && app.server.address();
    if (ad && typeof ad === "object" && ad.port) return ad.port;
  } catch (e) {}
  return 9988;
}
function hsdOrigin(){ return "http://127.0.0.1:" + hsdPort(); }
function hsdFixUrl(u){
  var s = String(u || "");
  if (/^https?:\/\/(127\.0\.0\.1|localhost)([:/]|$)/i.test(s) && !/^https?:\/\/(127\.0\.0\.1|localhost):\d+/i.test(s)) {
    return hsdOrigin() + s.replace(/^https?:\/\/(127\.0\.0\.1|localhost)/i, "");
  }
  return s;
}
function hsdClean(s){
  return String(s == null ? "" : s)
    .replace(/from\s+\w+/ig, " ")
    .replace(/[【】\[\]()（）《》]/g, " ")
    .replace(/第\s*\d+\s*[集话期]/g, " ")
    .replace(/[·・|｜\-—_:：、,，.。!！?？'"“”]/g, " ")
    .replace(/\s+/g, " ").trim();
}
var HSD_BAD = ["动态漫","动态漫画","特别版","特辑","番外","外传","前传","后传","舞台剧","真人版","纯享","精华","解说","混剪","片段","花絮","预告","角色篇","精剪","合集","合辑","全集","年番","重制","总集篇"];
function hsdScore(cand, name, ep){
  var cn = hsdClean(cand && cand.name), tn = hsdClean(name);
  if (!tn) return 0;
  var s = 0, pos = cn.indexOf(tn);
  if (cn === tn) s += 60;
  else if (pos >= 0) {
    s += 50;
    var after = cn.slice(pos + tn.length).trim();
    if (/^(\d{1,3})\b/.test(after) && !/\d/.test(tn)) s -= 16;
    if (after) s -= 4;
  } else {
    var toks = tn.split(" ").filter(Boolean), hit = 0;
    for (var i = 0; i < toks.length; i++) if (cn.indexOf(toks[i]) >= 0) hit++;
    s += toks.length ? Math.round(28 * hit / toks.length) : 0;
  }
  if (pos === 0) s += 22;
  if (/第\s*\d+\s*季/.test(cn) && !/第\s*\d+\s*季/.test(tn)) s -= 6;
  var m = cn.match(/第\s*(\d+)\s*[集话期]/) || cn.match(/[_\- ](\d{1,3})$/);
  if (m) { if (Number(m[1]) === Number(ep)) s += 55; else s -= 25; }
  else { if (Number(ep) > 1) s -= 20; else s += 6; }
  for (var j = 0; j < HSD_BAD.length; j++) { if (String(cand.name).indexOf(HSD_BAD[j]) >= 0) { s -= 20; break; } }
  if (/tencent|qq/i.test(cand.name)) s += 6;
  else if (/bilibili/i.test(cand.name)) s += 3;
  else if (/iqiyi/i.test(cand.name)) s += 2;
  return s;
}
function hsdInner(pathWithQuery){
  return hsdEnsure().then(function(mod){
    var WebReq = (mod.WebRequest || (typeof Request !== "undefined" ? Request : null));
    if (!WebReq) throw new Error("no Web Request");
    return mod.handleRequest(new WebReq(hsdOrigin() + pathWithQuery), hsdEnvMap(HSD_CFG), "node", "127.0.0.1");
  });
}
function hsdMatch(name, ep, force){
  var key = String(name) + "|" + String(ep);
  var hit = HSD_MATCH.get(key);
  if (!force && hit && (Date.now() - hit.at) < HSD_MATCH_TTL) return Promise.resolve(Object.assign({ cached: true }, hit));
  if (!force && HSD_INFLIGHT.has(key)) return HSD_INFLIGHT.get(key);   // P4：并发合并
  var app = HSD_STATE && HSD_STATE.app;
  var p = hsdCfg(app && app.db).then(function(cfg){
    HSD_CFG = Object.assign({}, HSD_CFG, cfg);
    return hsdInner("/api/v2/fongmi/danmaku?name=" + encodeURIComponent(name) + "&episode=" + encodeURIComponent(String(ep)));
  }).then(function(res){ return res.json(); }).then(function(cands){
    if (!Array.isArray(cands) || !cands.length) return { ok: false, reason: "no candidates" };
    var seen = {}, list = [];
    cands.forEach(function(c){
      if (!c || !c.name || !c.url || seen[c.name]) return;
      seen[c.name] = 1;
      c.score = hsdScore(c, name, ep);
      list.push(c);
    });
    if (!list.length) return { ok: false, reason: "no usable candidates" };
    list.sort(function(a, b){ return b.score - a.score; });
    var top = list.slice(0, 5);   // P7: 并行多试几个源（个别平台 500/空时仍能命中）
    return Promise.all(top.map(function(c){
      return hsdInner(hsdFixUrl(c.url).replace(/^https?:\/\/[^/]+/i, ""))
        .then(function(r){ return r.text(); })
        .then(function(t){ return (t.indexOf("<i>") >= 0) ? { c: c, xml: t, n: (t.match(/<d p=/g) || []).length } : null; })
        .catch(function(){ return null; });
    })).then(function(rs){
      var ok = rs.filter(Boolean).sort(function(a, b){ return b.n - a.n; });
      if (!ok.length) return { ok: false, reason: "all xml failed" };
      var w = ok[0];
      var out = { ok: true, xml: w.xml, picked: w.c, dmCount: w.n, candidates: list.length, at: Date.now(),
                  top3: list.slice(0, 3).map(function(x){ return { n: String(x.name).slice(0, 42), s: x.score }; }) };
      HSD_MATCH.set(key, out);
      while (HSD_MATCH.size > HSD_CACHE_MAX) HSD_MATCH.delete(HSD_MATCH.keys().next().value);
      return out;
    });
  });
  if (!force) {
    HSD_INFLIGHT.set(key, p);
    p.then(function(){ HSD_INFLIGHT.delete(key); }, function(){ HSD_INFLIGHT.delete(key); });
  }
  return p;
}
function hsdTruthy(v){
  if (v === true || v === 1) return true;
  var t = String(v == null ? "" : v).trim().toLowerCase();
  return t === "true" || t === "1" || t === "yes" || t === "on";
}
function hsdIsNoDanmu(obj){
  try {
    if (!obj || typeof obj !== "object") return false;
    if (hsdTruthy(obj.nodanmu)) return true;
    if (obj.extra && hsdTruthy(obj.extra.nodanmu)) return true;
  } catch (e) {}
  return false;
}
function hsdEpFromName(s){
  var m = String(s == null ? "" : s).match(/[0-9]+/);
  if (!m) return 0;
  var n = Number(m[0]);
  return (n > 0 && n < 10000) ? n : 0;
}
function hsdPushDanmu(url, tag, key){
  try {
    if (key) {
      var now = Date.now();
      if (HSD_PUSH.key === key && now - HSD_PUSH.at < 30000) {
        console.log("[hsd] auto push 去重跳过：" + key);
        return false;
      }
      HSD_PUSH.key = key; HSD_PUSH.at = now;
    }
    if (typeof globalThis.messageToDart !== "function") return false;
    globalThis.messageToDart({ action: "danmuPush", opt: { url: url } });
    console.log("[hsd] danmuPush(" + tag + ")：" + url);
    return true;
  } catch (e) {
    console.error("[hsd] danmuPush 异常：" + ((e && e.message) || e));
    return false;
  }
}
function hsdAutoPushSoon(info){
  try {
    if (HSD_CFG.push === false) return;
    setTimeout(function(){
      if (info) { hsdPushDanmu(hsdAutoUrl(info.name, info.ep), "learned", info.name + "|" + info.ep); return; }
      try {
        if (typeof globalThis.messageToDart !== "function") return;
        var r = globalThis.messageToDart({ action: "getPlayInfo", opt: {} });
        if (!r || typeof r.then !== "function") return;
        r.then(function(n){
          var title = n && n.title ? String(n.title).trim() : "";
          if (!title) { console.log("[hsd] auto push 跳过：壳未给出播放信息"); return; }
          var ep = hsdEpFromName(n && n.episodeName) || 1;
          hsdPushDanmu(hsdAutoUrl(title, ep), "playinfo", title + "|" + ep);
        }).catch(function(){});
      } catch (e) {}
    }, 800);
  } catch (e) {}
}

function hsdEscapeHtml(s){
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function hsdSearchPageHtml(kw){
  var k = hsdEscapeHtml(kw);
  var h = '';
  h += '<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8">';
  h += '<meta name="viewport" content="width=device-width,initial-scale=1">';
  h += '<title>弹幕搜索</title><style>';
  h += 'body{font-family:-apple-system,"PingFang SC",sans-serif;margin:0;padding:18px;background:#101014;color:#e8e8ea}';
  h += 'h3{margin:4px 0 14px}';
  h += 'input{font-size:16px;padding:9px 11px;border-radius:9px;border:1px solid #333;background:#1c1c22;color:#eee;outline:none}';
  h += 'button{font-size:16px;padding:9px 16px;border-radius:9px;border:0;background:#3a6df0;color:#fff}';
  h += '#r{margin-top:16px;font-size:13px;line-height:1.6;white-space:pre-wrap;word-break:break-all}a{color:#6cf}';
  h += '</style></head><body>';
  h += '<h3>弹幕搜索</h3>';
  h += '<div><input id="k" placeholder="剧名" value="' + k + '" style="width:52%"> ';
  h += '<input id="e" placeholder="集" value="1" style="width:14%"> ';
  h += '<button onclick="go()">查询</button></div>';
  h += '<div id="r"></div>';
  h += '<script>';
  h += 'function go(){';
  h += 'var k=document.getElementById("k").value.trim();';
  h += 'var e=document.getElementById("e").value.trim()||"1";';
  h += 'var r=document.getElementById("r");r.textContent="查询中...";';
  h += 'fetch("/danmu/match?name="+encodeURIComponent(k)+"&episode="+encodeURIComponent(e))';
  h += '.then(function(x){return x.json()}).then(function(j){';
  h += 'r.textContent="";';
  h += 'if(j&&j.code===0){var a=document.createElement("a");';
  h += 'a.href="/danmu/auto?name="+encodeURIComponent(k)+"&episode="+encodeURIComponent(e)+"&format=xml";';
  h += 'a.textContent="弹幕 XML（"+(j.dmCount||0)+" 条）";r.appendChild(a);r.appendChild(document.createElement("br"));}';
  h += 'var d=document.createElement("div");d.textContent=JSON.stringify(j,null,2);r.appendChild(d);';
  h += '}).catch(function(err){r.textContent="失败: "+err;});';
  h += '}';
  h += '</script></body></html>';
  return h;
}
function hsdSearchPage(req, reply){
  try {
    var q = (req && req.query) || {};
    reply.type("text/html; charset=utf-8");
    return reply.send(hsdSearchPageHtml(q.keyword || q.name || ""));
  } catch (e) {
    reply.code(500);
    return reply.send("search page error");
  }
}
var HSD_PREWARM = new Map();
function hsdPrewarm(name){
  try {
    name = String(name || "").trim();
    if (!name) return;
    var now = Date.now();
    var last = HSD_PREWARM.get(name) || 0;
    if (now - last < 30 * 60 * 1000) return;
    HSD_PREWARM.set(name, now);
    if (HSD_PREWARM.size > 80) { var it = HSD_PREWARM.keys().next(); if (!it.done) HSD_PREWARM.delete(it.value); }
    console.log("[hsd] 详情预热匹配：" + name + " ep1");
    hsdMatch(name, 1).catch(function(){});
  } catch (e) {}
}
function hsdAutoUrl(name, ep){
  return hsdOrigin() + "/danmu/auto?name=" + encodeURIComponent(name) + "&episode=" + encodeURIComponent(String(ep));
}
function hsdAutoHandler(req, reply){
  if (String(req.method || "").toUpperCase() === "OPTIONS") return reply.code(204).send("");
  var q = req.query || {};
  var name = String(q.name || q.wd || q.keyword || "").trim();
  var ep = Number(q.episode || q.ep || 1) || 1;
  if (!name) { reply.code(400); return reply.send({ code: -1, message: "missing name" }); }
  return hsdMatch(name, ep, q.refresh === "1" || q.force === "1").then(function(r){
    if (!r || !r.ok) {
      console.log("[hsd] auto 无结果→空XML：" + name + " ep" + ep + "（" + ((r && r.reason) || "?") + "）");
      if (String(q.format || "").toLowerCase() === "json") { reply.code(404); return reply.send({ code: -1, message: (r && r.reason) || "no danmu" }); }
      reply.header("Content-Type", "application/xml");
      reply.header("Access-Control-Allow-Origin", "*");
      return reply.send("<?xml version=\"1.0\" ?>\n<i></i>");
    }
    if (String(q.format || "").toLowerCase() === "json") {
      return reply.send({ code: 0, name: name, episode: ep, count: r.dmCount, source: r.picked && r.picked.name, xml: r.xml });
    }
    reply.header("Content-Type", "application/xml");
    reply.header("Access-Control-Allow-Origin", "*");
    return reply.send(r.xml);
  }).catch(function(e){
    console.log("[hsd] auto 异常→空XML：" + ((e && e.message) || e));
    if (String(q.format || "").toLowerCase() === "json") { reply.code(502); return reply.send({ code: -1, message: "danmu error: " + ((e && e.message) || e) }); }
    reply.header("Content-Type", "application/xml");
    reply.header("Access-Control-Allow-Origin", "*");
    return reply.send("<?xml version=\"1.0\" ?>\n<i></i>");
  });
}
function hsdMatchHandler(req, reply){
  var q = req.query || {};
  var name = String(q.name || q.keyword || "").trim();
  var ep = Number(q.episode || q.ep || 1) || 1;
  if (!name) { reply.code(400); return reply.send({ code: -1, message: "missing name" }); }
  return hsdMatch(name, ep, q.force === "1").then(function(r){
    if (!r || !r.ok) { reply.code(404); return reply.send({ code: -1, message: (r && r.reason) || "no danmu" }); }
    return reply.send({ code: 0, cached: !!r.cached, candidates: r.candidates, dmCount: r.dmCount,
      picked: r.picked && r.picked.name, url: hsdAutoUrl(name, ep), top3: r.top3 });
  }).catch(function(e){ reply.code(502); return reply.send({ code: -1, message: String((e && e.message) || e) }); });
}
function hsdLearnDetail(obj){
  try {
    var list = obj && obj.list;
    if (!Array.isArray(list)) return 0;
    var n = 0;
    list.forEach(function(v){
      var name = String((v && v.vod_name) || "").trim();
      var pu = String((v && v.vod_play_url) || "");
      if (!name || !pu) return;
      pu.split("#").forEach(function(seg, idx){
        var p = String(seg).split("$");
        var epName = p[0] || "", epUrl = p[1] || "";
        if (!epUrl) return;
        var m = String(epName).match(/(\d+)/);
        var ep = m ? Number(m[1]) : (idx + 1);
        if (HSD_DETAIL.size > 2000) HSD_DETAIL.delete(HSD_DETAIL.keys().next().value);
        HSD_DETAIL.set(epUrl, { name: name, ep: ep, at: Date.now() });
        n++;
      });
    });
    if (n) console.log("[hsd] detail 学习：" + n + " 集（表 " + HSD_DETAIL.size + "）");
    try { hsdPrewarm(name); } catch (e5) {}
    return n;
  } catch (e) { return 0; }
}
function hsdPreHandler(req, rep, done){
  try {
    var p = String((req.url || "").split("?")[0]);
    if (/^\/spider\/[^\/]+\/3\/play$/.test(p)) {
      var id = "";
      if (req.body && req.body.id != null) id = String(req.body.id);
      else if (req.query && req.query.id != null) id = String(req.query.id);
      req.__hsdPlayId = id;
    }
  } catch (e) {}
  return done();
}
function hsdLookupPlay(req, obj){
  var cands = [];
  try {
    if (req.__hsdPlayId) cands.push(String(req.__hsdPlayId));
    if (req.body && req.body.id != null) cands.push(String(req.body.id));
    if (req.query && req.query.id != null) cands.push(String(req.query.id));
    if (obj && obj.url) cands.push(String(obj.url));
  } catch (e) {}
  for (var i = 0; i < cands.length; i++) {
    var hit = HSD_DETAIL.get(cands[i]);
    if (hit && (Date.now() - hit.at) < HSD_DETAIL_TTL) return hit;
  }
  return null;
}
function hsdOnSend(req, rep, payload, done){
  try {
    if (typeof payload !== "string" || !payload) return done(null, payload);
    var path = String((req.url || "").split("?")[0]);
    var seg = path.split("/").filter(Boolean);
    if (seg.length >= 4 && seg[0] === "spider" && seg[3] === "detail") {
      try { hsdLearnDetail(JSON.parse(payload)); } catch (e) {}
      return done(null, payload);
    }
    if (!(seg.length >= 4 && seg[0] === "spider" && seg[3] === "play" && String(seg[2]) === "3")) return done(null, payload);
    if (path.indexOf("liveSource") >= 0 || path.indexOf("qrcode") >= 0) return done(null, payload);
    var cfg = HSD_CFG;
    var obj = JSON.parse(payload);
    if (!obj || typeof obj !== "object" || Array.isArray(obj)) return done(null, payload);
    if (hsdIsNoDanmu(obj)) { console.log("[hsd] play 源标记 nodanmu，跳过"); return done(null, payload); }
    var info = hsdLookupPlay(req, obj);
    console.log("[hsd] play " + (info ? ("命中：" + info.name + " ep" + info.ep) : "未命中（id=" + (req.__hsdPlayId || "?") + "，表 " + HSD_DETAIL.size + "）"));
    var out = payload;
    if (info) {
      var u = hsdAutoUrl(info.name, info.ep);
      if (cfg.inject !== false && !(obj.extra && obj.extra.danmaku)) {
        obj.extra = Object.assign({}, obj.extra || {}, { danmaku: u, nodanmu: false });
        out = JSON.stringify(obj);
        console.log("[hsd] play 注入弹幕 URL：" + info.name + " ep" + info.ep);
      }
      if (cfg.push !== false) {
        try { hsdMatch(info.name, info.ep).catch(function(){}); } catch (e4) {}
      }
    }
    if (cfg.push !== false) hsdAutoPushSoon(info);
    return done(null, out);
  } catch (e) {
    return done(null, payload);
  }
}
